// Pick up production orders that have not been announced to the shop floor yet,
// and build one short message per order. Nothing here is company specific —
// change the column names in Settings, not this code.
const cfg = $('Set Order Fields').first().json;

const COL = {
  id:       cfg.colOrderId   || 'Order',
  product:  cfg.colProduct   || 'Product',
  qty:      cfg.colQuantity  || 'Quantity',
  due:      cfg.colDueDate   || 'Due date',
  station:  cfg.colStation   || 'Station',
  status:   cfg.colStatus    || 'Announced',
  priority: cfg.colPriority  || 'Priority',
};
const DONE = (cfg.announcedValue || 'yes').toLowerCase();
const MAX  = Number(cfg.maxPerRun || 20);

const rows = $input.all().map(i => i.json);
const pending = rows.filter(r => {
  const flag = String(r[COL.status] ?? '').trim().toLowerCase();
  const hasId = String(r[COL.id] ?? '').trim() !== '';
  return hasId && flag !== DONE;
});

if (!pending.length) return [];

function daysLeft(v) {
  if (!v) return null;
  const d = new Date(v);
  if (isNaN(d)) return null;
  return Math.ceil((d - new Date()) / 86400000);
}

const out = [];
for (const r of pending.slice(0, MAX)) {
  const left = daysLeft(r[COL.due]);
  const urgent = left !== null && left <= Number(cfg.urgentDays || 2);

  const lines = [];
  lines.push((urgent ? '🔴 ' : '🔵 ') + 'ORDER ' + String(r[COL.id]));
  if (r[COL.product])  lines.push('Product: ' + r[COL.product]);
  if (r[COL.qty])      lines.push('Quantity: ' + r[COL.qty]);
  if (r[COL.station])  lines.push('Station: ' + r[COL.station]);
  if (r[COL.due])      lines.push('Due: ' + r[COL.due] + (left !== null ? '  (' + left + ' days)' : ''));
  if (r[COL.priority]) lines.push('Priority: ' + r[COL.priority]);

  out.push({ json: {
    order_id: String(r[COL.id]),
    row_number: r.row_number ?? null,
    urgent,
    days_left: left,
    text: lines.join('\n'),
  }});
}

// Newest deadline first — the shop floor should see what burns, not what is alphabetically first.
out.sort((a, b) => (a.json.days_left ?? 9999) - (b.json.days_left ?? 9999));
return out;
